def count_pairs_with_sum(nums, target):
    """
    Returns the number of distinct pairs in nums that add up to the target sum.
    """
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(pairs)

