def count_pairs_with_xor(nums, k):
    """
    Returns the number of pairs (i, j) where 0 <= i < j < len(nums)
    and nums[i] xor nums[j] is equal to the given integer k.
    """
    count = 0
    n = len(nums)

    # Iterate through all pairs (i, j) and calculate nums[i] xor nums[j]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] ^ nums[j] == k:
                count += 1

    return count

