def min_shelves(n, maxThickness, maxHeight, books):
    shelves = []

    for book in books:
        added_to_shelf = False
        for i in range(len(shelves)):
            current_shelf_thick = sum(b[0] for b in shelves[i])
            current_shelf_height = max(b[1] for b in shelves[i])
            if current_shelf_thick + book[0] <= maxThickness and book[1] <= maxHeight:
                shelves[i].append(book)
                added_to_shelf = True
                break

        if not added_to_shelf:
            if book[1] <= maxHeight:
                shelves.append([book])
            else:
                return -1

    return len(shelves)

