def maximum_wealth(n, m, wealth, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)

    # Initialize distance and wealth array
    max_wealth = [-1] * (n + 1)
    max_wealth[1] = wealth[0]

    queue = deque([1])

    while queue:
        curr = queue.popleft()
        for neighbor in graph[curr]:
            if max_wealth[neighbor] < max_wealth[curr] + wealth[neighbor - 1]:
                max_wealth[neighbor] = max_wealth[curr] + wealth[neighbor - 1]
                queue.append(neighbor)

    return max_wealth[n] if max_wealth[n] != -1 else -1

