def can_be_palindrome(s):
    """
    Determines if the given string can be transformed into a valid palindrome 
    by replacing each '?' with appropriate characters.
    """
    n = len(s)
    for i in range(n // 2):
        if s[i] == '?' or s[n - i - 1] == '?':
            continue
        if s[i] != s[n - i - 1]:
            return "NO"

    return "YES"

