from typing import List

def sparse_matrix_multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    if not A or not B or not A[0] or not B[0]:
        return []

    m, n = len(A), len(A[0])
    nB, p = len(B), len(B[0])

    assert n == nB, "Number of columns in A must be equal to the number of rows in B"

    result = [[0] * p for _ in range(m)]

    # Iterate over the matrix A.
    for i in range(m):
        for k in range(n):
            if A[i][k] != 0:
                for j in range(p):
                    if B[k][j] != 0:
                        result[i][j] += A[i][k] * B[k][j]

    return result

