def longest_increasing_subsequence(n, sequence):
    if n == 1:
        return 1, [sequence[0]]

    lengths = [1] * n
    previous_index = [-1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j] and lengths[i] < lengths[j] + 1:
                lengths[i] = lengths[j] + 1
                previous_index[i] = j

    max_length = max(lengths)
    max_index = lengths.index(max_length)

    lis = []
    while max_index != -1:
        lis.append(sequence[max_index])
        max_index = previous_index[max_index]

    lis.reverse()

    return max_length, lis

