def maxSumNonAdjacent(nums):
    """
    Returns the maximum sum of non-adjacent elements in the array.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    include = 0
    exclude = 0

    for num in nums:
        new_exclude = max(include, exclude)
        include = exclude + num
        exclude = new_exclude

    return max(include, exclude)

def wiggle_sort(nums):
    """
    This function reorders the array 'nums' such that it satisfies the wiggle sort condition.
    That is, 
        nums[0] <= nums[1] >= nums[2] <= nums[3] >= ...
    """
    for i in range(len(nums) - 1):
        if (i % 2 == 0 and nums[i] > nums[i + 1]) or (i % 2 != 0 and nums[i] < nums[i + 1]):
            # Swap elements if they do not satisfy the wiggle condition
            nums[i], nums[i + 1] = nums[i + 1], nums[i]

