def longest_run(cards):
    if len(cards) < 2:
        return 0

    max_length = 1
    current_length = 1
    current_diff = cards[1] - cards[0]

    for i in range(1, len(cards) - 1):
        diff = cards[i + 1] - cards[i]
        if diff == current_diff:
            current_length += 1
        else:
            current_diff = diff
            current_length = 1

        max_length = max(max_length, current_length + 1)

    return max_length

