def max_items(N, k, items):
    current_index = k - 1  # Convert k to zero-based index
    forward_sum = 0
    backward_sum = 0

    # Calculate the maximum items by moving forward
    for i in range(current_index, N):
        forward_sum += items[i]

    # Calculate the maximum items by moving backward
    for i in range(current_index, -1, -1):
        backward_sum += items[i]

    # Return the maximum of the two sums
    return max(forward_sum, backward_sum)

