import heapq

def shortest_travel_time(n, edges, a, b):
    """
    Returns the shortest travel time from intersection a to intersection b.

    :param n: Integer, number of intersections.
    :param edges: List of lists, each containing three integers [u, v, w]
                  representing a road between intersections u and v with travel time w.
    :param a: Integer, starting intersection.
    :param b: Integer, ending intersection.
    :return: Integer, minimum travel time if a path exists, or -1 if no path exists.
    """
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_heap = [(0, a)]  # (cost, node)
    min_time = {i: float('inf') for i in range(n)}
    min_time[a] = 0

    while min_heap:
        curr_time, u = heapq.heappop(min_heap)

        if u == b:
            return curr_time

        if curr_time > min_time[u]:
            continue

        for v, weight in graph[u]:
            time = curr_time + weight
            if time < min_time[v]:
                min_time[v] = time
                heapq.heappush(min_heap, (time, v))

    return -1 if min_time[b] == float('inf') else min_time[b]

def find_first_activity_repeated_k_times(T, test_cases):
    results = []
    for i in range(T):
        N, K = test_cases[i][0]
        activities = test_cases[i][1]

        activity_count = {}

        for activity in activities:
            if activity in activity_count:
                activity_count[activity] += 1
            else:
                activity_count[activity] = 1

            if activity_count[activity] == K:
                results.append(activity)
                break
        else:
            results.append(-1)
    return results

