def min_increasing_subseq_sum(arr):
    """
    Returns the minimum sum of a non-empty increasing subsequence of arr.
    """
    if not arr:
        return 0

    n = len(arr)
    min_sum = [float('inf')] * n

    # Initialize min_sum array with values of arr
    for i in range(n):
        min_sum[i] = arr[i]

    # Find the minimum sum of an increasing subsequence
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and min_sum[i] > arr[i] + min_sum[j]:
                min_sum[i] = arr[i] + min_sum[j]

    # The result is the minimum value in the min_sum array
    return min(min_sum)

